(function(){try{var q=new URLSearchParams(location.search),s=sessionStorage,d=document.documentElement,P=["navy-gold","ivory-brass","midnight-gold"],H=["montserrat","cormorant"];if(q.get("preview")==="off"){s.removeItem("dg-preview-preset");s.removeItem("dg-preview-headings")}var p=q.get("preset"),h=q.get("headings");if(P.indexOf(p)>-1)s.setItem("dg-preview-preset",p);if(H.indexOf(h)>-1)s.setItem("dg-preview-headings",h);p=s.getItem("dg-preview-preset");h=s.getItem("dg-preview-headings");if(P.indexOf(p)>-1)d.setAttribute("data-preset",p);if(H.indexOf(h)>-1)d.setAttribute("data-headings",h)}catch(e){}})()